CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT NOT NULL, username TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK(role IN ('manager','member')), password TEXT, active INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), expires TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY, kind TEXT NOT NULL, body TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created TEXT NOT NULL, updated TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS documents_kind ON documents(kind,archived);
CREATE TABLE IF NOT EXISTS history(seq INTEGER PRIMARY KEY AUTOINCREMENT, entity TEXT NOT NULL, actor INTEGER, action TEXT NOT NULL, at TEXT NOT NULL, snapshot TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS history_entity ON history(entity,seq);
CREATE TRIGGER IF NOT EXISTS history_no_update BEFORE UPDATE ON history BEGIN SELECT RAISE(ABORT,'History is append-only'); END;
CREATE TRIGGER IF NOT EXISTS history_no_delete BEFORE DELETE ON history BEGIN SELECT RAISE(ABORT,'History is append-only'); END;
CREATE TABLE IF NOT EXISTS idempotency(key TEXT NOT NULL, actor INTEGER NOT NULL, fingerprint TEXT NOT NULL, response TEXT NOT NULL, PRIMARY KEY(key,actor));
CREATE TABLE IF NOT EXISTS occurrences(schedule_id TEXT NOT NULL, day TEXT NOT NULL, task_id TEXT NOT NULL, PRIMARY KEY(schedule_id,day));
CREATE TABLE IF NOT EXISTS login_attempts(key TEXT NOT NULL, at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1), body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), message TEXT NOT NULL, task_id TEXT, at TEXT NOT NULL, seen INTEGER NOT NULL DEFAULT 0, dedupe TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS schema_migrations(version TEXT PRIMARY KEY, applied TEXT NOT NULL);
